using System;
using System.Diagnostics;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace WordToPdfConverter.Services.Remediation.AI
{
    /// <summary>
    /// Executes remediation scripts generated by GPT-5 in a safe environment
    /// </summary>
    public class ScriptExecutor
    {
        private readonly ILogger<ScriptExecutor> _logger;
        private readonly string _scriptDirectory;

        public ScriptExecutor(ILogger<ScriptExecutor> logger)
        {
            _logger = logger;
            _scriptDirectory = Path.Combine(Path.GetTempPath(), "pdf-remediation-scripts");
            Directory.CreateDirectory(_scriptDirectory);
        }

        /// <summary>
        /// Execute a Python script for PDF remediation
        /// </summary>
        public async Task<ScriptResult> ExecutePythonScriptAsync(
            string script,
            byte[] inputPdf,
            string scriptType = "remediation")
        {
            var result = new ScriptResult();
            var sessionId = Guid.NewGuid().ToString("N");

            try
            {
                // Create session directory
                var sessionDir = Path.Combine(_scriptDirectory, sessionId);
                Directory.CreateDirectory(sessionDir);

                // Save input PDF
                var inputPath = Path.Combine(sessionDir, "input.pdf");
                var outputPath = Path.Combine(sessionDir, "output.pdf");
                var scriptPath = Path.Combine(sessionDir, "remediate.py");
                var logPath = Path.Combine(sessionDir, "execution.log");

                await File.WriteAllBytesAsync(inputPath, inputPdf);

                // Prepare the script with proper paths and error handling
                var fullScript = PrepareScript(script, inputPath, outputPath);
                await File.WriteAllTextAsync(scriptPath, fullScript);

                _logger.LogInformation($"[SCRIPT-EXECUTOR] Executing Python script in session {sessionId}");

                // Execute the script
                using var process = new Process
                {
                    StartInfo = new ProcessStartInfo
                    {
                        FileName = "python3",
                        Arguments = scriptPath,
                        RedirectStandardOutput = true,
                        RedirectStandardError = true,
                        UseShellExecute = false,
                        CreateNoWindow = true,
                        WorkingDirectory = sessionDir
                    }
                };

                var outputBuilder = new StringBuilder();
                var errorBuilder = new StringBuilder();

                process.OutputDataReceived += (sender, e) =>
                {
                    if (e.Data != null)
                    {
                        outputBuilder.AppendLine(e.Data);
                        _logger.LogDebug($"[SCRIPT-OUTPUT] {e.Data}");
                    }
                };

                process.ErrorDataReceived += (sender, e) =>
                {
                    if (e.Data != null)
                    {
                        errorBuilder.AppendLine(e.Data);

                        // Parse Python log level and log appropriately
                        var line = e.Data;
                        if (line.StartsWith("INFO:"))
                        {
                            _logger.LogInformation($"[SCRIPT-INFO] {line.Substring(5)}");
                        }
                        else if (line.StartsWith("WARNING:"))
                        {
                            _logger.LogWarning($"[SCRIPT-WARNING] {line.Substring(8)}");
                        }
                        else if (line.StartsWith("ERROR:") || line.StartsWith("CRITICAL:"))
                        {
                            _logger.LogError($"[SCRIPT-ERROR] {line}");
                        }
                        else if (line.StartsWith("DEBUG:"))
                        {
                            _logger.LogDebug($"[SCRIPT-DEBUG] {line.Substring(6)}");
                        }
                        else
                        {
                            // Unknown format, log as warning to be safe
                            _logger.LogWarning($"[SCRIPT-STDERR] {line}");
                        }
                    }
                };

                process.Start();
                process.BeginOutputReadLine();
                process.BeginErrorReadLine();

                // Wait for completion with timeout
                var completed = await Task.Run(() => process.WaitForExit(120000)); // 2 minute timeout

                if (!completed)
                {
                    process.Kill();
                    throw new TimeoutException("Script execution timed out");
                }

                result.ExitCode = process.ExitCode;
                result.StandardOutput = outputBuilder.ToString();
                result.StandardError = errorBuilder.ToString();
                result.Success = process.ExitCode == 0;

                // Save execution log
                var logContent = $"Exit Code: {result.ExitCode}\n\nOutput:\n{result.StandardOutput}\n\nErrors:\n{result.StandardError}";
                await File.WriteAllTextAsync(logPath, logContent);

                // Read output PDF if successful
                if (result.Success && File.Exists(outputPath))
                {
                    result.OutputPdf = await File.ReadAllBytesAsync(outputPath);
                    _logger.LogInformation($"[SCRIPT-EXECUTOR] Script completed successfully, output PDF size: {result.OutputPdf.Length} bytes");
                }
                else
                {
                    _logger.LogWarning($"[SCRIPT-EXECUTOR] Script failed or no output generated");
                }

                // Cleanup session directory (optional - keep for debugging)
                if (result.Success)
                {
                    try
                    {
                        Directory.Delete(sessionDir, true);
                    }
                    catch
                    {
                        // Ignore cleanup errors
                    }
                }

                return result;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "[SCRIPT-EXECUTOR] Script execution failed");
                result.Success = false;
                result.ErrorMessage = ex.Message;
                return result;
            }
        }

