        /// <summary>
        /// Prepare the script with proper imports and error handling
        /// </summary>
        private string PrepareScript(string script, string inputPath, string outputPath)
        {
            var sb = new StringBuilder();

            // Always add essential imports (needed for error handling)
            if (!script.Contains("import sys"))
            {
                sb.AppendLine("import sys");
            }
            if (!script.Contains("import os"))
            {
                sb.AppendLine("import os");
            }
            if (!script.Contains("import traceback"))
            {
                sb.AppendLine("import traceback");
            }
            sb.AppendLine();

            // Add input/output path variables
            sb.AppendLine($"INPUT_PDF = r'{inputPath}'");
            sb.AppendLine($"OUTPUT_PDF = r'{outputPath}'");
            sb.AppendLine();

            // Add the main script
            sb.AppendLine("try:");

            // Indent the user's script
            var lines = script.Split('\n');
            foreach (var line in lines)
            {
                sb.AppendLine($"    {line}");
            }

            // Add error handling
            sb.AppendLine("\nexcept Exception as e:");
            sb.AppendLine("    print(f'ERROR: {e}', file=sys.stderr)");
            sb.AppendLine("    traceback.print_exc(file=sys.stderr)");
            sb.AppendLine("    sys.exit(1)");

            // Ensure output file exists
            sb.AppendLine("\nif not os.path.exists(OUTPUT_PDF):");
            sb.AppendLine("    print('ERROR: Output PDF not created', file=sys.stderr)");
            sb.AppendLine("    sys.exit(1)");

            sb.AppendLine("\nprint(f'Successfully created {OUTPUT_PDF}')");
            sb.AppendLine("sys.exit(0)");

            return sb.ToString();
        }

        /// <summary>
        /// Install required Python packages if needed
        /// </summary>
        public async Task<bool> EnsurePythonDependenciesAsync()
        {
            try
            {
                // Check if required packages are installed
                var packages = new[] { "pikepdf", "PyPDF2", "reportlab", "pypdf" };

                foreach (var package in packages)
                {
                    var checkProcess = Process.Start(new ProcessStartInfo
                    {
                        FileName = "python3",
                        Arguments = $"-c \"import {package}\"",
                        RedirectStandardOutput = true,
                        RedirectStandardError = true,
                        UseShellExecute = false,
                        CreateNoWindow = true
                    });

                    await Task.Run(() => checkProcess.WaitForExit(5000));

                    if (checkProcess.ExitCode != 0)
                    {
                        _logger.LogInformation($"[SCRIPT-EXECUTOR] Installing Python package: {package}");

                        var installProcess = Process.Start(new ProcessStartInfo
                        {
                            FileName = "pip3",
                            Arguments = $"install {package}",
                            RedirectStandardOutput = true,
                            RedirectStandardError = true,
                            UseShellExecute = false,
                            CreateNoWindow = true
                        });

                        await Task.Run(() => installProcess.WaitForExit(60000));

                        if (installProcess.ExitCode != 0)
                        {
                            _logger.LogWarning($"[SCRIPT-EXECUTOR] Failed to install {package}");
                        }
                    }
                }

                return true;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "[SCRIPT-EXECUTOR] Failed to ensure Python dependencies");
                return false;
            }
        }
    }

    public class ScriptResult
    {
        public bool Success { get; set; }
        public byte[] OutputPdf { get; set; }
        public string StandardOutput { get; set; }
        public string StandardError { get; set; }
        public int ExitCode { get; set; }
        public string ErrorMessage { get; set; }
    }
}